  1→import { useState } from "react";
  2→import type { LoaderFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher } from "react-router";
  4→import { authenticate } from "../shopify.server";
  5→import db from "../db.server";
  6→import { getPlan, hasFeature } from "../lib/plans";
  7→
  8→// ---------------------------------------------------------------------------
  9→// Types
 10→// ---------------------------------------------------------------------------
 11→
 12→interface DailyDataPoint {
 13→  label: string;
 14→  value: number;
 15→}
 16→
 17→interface TopChart {
 18→  chartId: string | null;
 19→  chartName: string;
 20→  views: number;
 21→  rank: number;
 22→}
 23→
 24→// ---------------------------------------------------------------------------
 25→// Loader
 26→// ---------------------------------------------------------------------------
 27→
 28→export const loader = async ({ request }: LoaderFunctionArgs) => {
 29→  const { session } = await authenticate.admin(request);
 30→  const shop = session.shop;
 31→
 32→  const url = new URL(request.url);
 33→  const fromParam = url.searchParams.get("from");
 34→  const toParam = url.searchParams.get("to");
 35→  const presetParam = url.searchParams.get("preset") ?? "30d";
 36→
 37→  // Resolve date range
 38→  const now = new Date();
 39→  let fromDate: Date;
 40→  let toDate: Date = new Date(now);
 41→  toDate.setHours(23, 59, 59, 999);
 42→
 43→  if (fromParam && toParam) {
 44→    fromDate = new Date(fromParam);
 45→    fromDate.setHours(0, 0, 0, 0);
 46→    const parsedTo = new Date(toParam);
 47→    parsedTo.setHours(23, 59, 59, 999);
 48→    toDate = parsedTo;
 49→  } else {
 50→    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
 51→    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
 52→    fromDate.setHours(0, 0, 0, 0);
 53→  }
 54→
 55→  const dateFilter = { gte: fromDate, lte: toDate };
 56→
 57→  const subscription = await db.subscription.findUnique({ where: { shop } });
 58→  const plan = getPlan(subscription?.planId ?? "free");
 59→  const canViewAnalytics = hasFeature(plan.id, "analytics");
 60→
 61→  if (!canViewAnalytics) {
 62→    return {
 63→      plan,
 64→      canViewAnalytics: false as const,
 65→      stats: null,
 66→      topChartsWithNames: [] as TopChart[],
 67→      dailyTrend: [] as DailyDataPoint[],
 68→      preset: presetParam,
 69→      fromDate: fromDate.toISOString().split("T")[0],
 70→      toDate: toDate.toISOString().split("T")[0],
 71→    };
 72→  }
 73→
 74→  const [
 75→    totalViews,
 76→    totalClicks,
 77→    totalRecommendations,
 78→    totalConverts,
 79→    topCharts,
 80→    rawEvents,
 81→  ] = await Promise.all([
 82→    db.analyticsEvent.count({ where: { shop, eventType: "view", createdAt: dateFilter } }),
 83→    db.analyticsEvent.count({ where: { shop, eventType: "click", createdAt: dateFilter } }),
 84→    db.analyticsEvent.count({ where: { shop, eventType: "recommend", createdAt: dateFilter } }),
 85→    db.analyticsEvent.count({ where: { shop, eventType: "convert", createdAt: dateFilter } }),
 86→    db.analyticsEvent.groupBy({
 87→      by: ["sizeChartId"],
 88→      where: { shop, eventType: "view", sizeChartId: { not: null }, createdAt: dateFilter },
 89→      _count: { id: true },
 90→      orderBy: { _count: { id: "desc" } },
 91→      take: 5,
 92→    }),
 93→    db.analyticsEvent.findMany({
 94→      where: { shop, eventType: "view", createdAt: dateFilter },
 95→      select: { createdAt: true },
 96→      orderBy: { createdAt: "asc" },
 97→    }),
 98→  ]);
 99→
100→  // Build daily trend bucketed by day
101→  const dayBuckets: Record<string, number> = {};
102→  const diffMs = toDate.getTime() - fromDate.getTime();
103→  const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
104→  for (let i = 0; i < Math.min(diffDays, 90); i++) {
105→    const d = new Date(fromDate.getTime() + i * 24 * 60 * 60 * 1000);
106→    const key = d.toISOString().split("T")[0];
107→    dayBuckets[key] = 0;
108→  }
109→  for (const ev of rawEvents) {
110→    const key = ev.createdAt.toISOString().split("T")[0];
111→    if (key in dayBuckets) dayBuckets[key]++;
112→  }
113→
114→  // Condense to max 30 bars for readability
115→  const bucketEntries = Object.entries(dayBuckets);
116→  const maxBars = 30;
117→  let dailyTrend: DailyDataPoint[];
118→  if (bucketEntries.length <= maxBars) {
119→    dailyTrend = bucketEntries.map(([date, value]) => ({
120→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
121→      value,
122→    }));
123→  } else {
124→    // Group into weekly buckets
125→    const weekBuckets: Record<string, number> = {};
126→    for (const [date, count] of bucketEntries) {
127→      const d = new Date(date + "T12:00:00Z");
128→      const weekStart = new Date(d);
129→      weekStart.setDate(d.getDate() - d.getDay());
130→      const wk = weekStart.toISOString().split("T")[0];
131→      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + count;
132→    }
133→    dailyTrend = Object.entries(weekBuckets).map(([date, value]) => ({
134→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
135→      value,
136→    }));
137→  }
138→
139→  // Resolve chart names
140→  const chartIds = topCharts.map((tc) => tc.sizeChartId).filter((id): id is string => id !== null);
141→  const charts = chartIds.length > 0
142→    ? await db.sizeChart.findMany({ where: { id: { in: chartIds }, shop }, select: { id: true, name: true } })
143→    : [];
144→
145→  const topChartsWithNames: TopChart[] = topCharts.map((tc, idx) => ({
146→    chartId: tc.sizeChartId,
147→    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
148→    views: tc._count.id,
149→    rank: idx + 1,
150→  }));
151→
152→  // Funnel rates
153→  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
154→  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
155→  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";
156→  const overallConvertRate = totalViews > 0 ? ((totalConverts / totalViews) * 100).toFixed(1) : "0";
157→
158→  return {
159→    plan,
160→    canViewAnalytics: true as const,
161→    stats: {
162→      totalViews,
163→      totalClicks,
164→      totalRecommendations,
165→      totalConverts,
166→      clickRate,
167→      recommendRate,
168→      convertRate,
169→      overallConvertRate,
170→    },
171→    topChartsWithNames,
172→    dailyTrend,
173→    preset: presetParam,
174→    fromDate: fromDate.toISOString().split("T")[0],
175→    toDate: toDate.toISOString().split("T")[0],
176→  };
177→};
178→
179→// ---------------------------------------------------------------------------
180→// BarChart sub-component (custom visualization — minimal inline styles)
181→// ---------------------------------------------------------------------------
182→
183→function BarChart({ data }: { data: DailyDataPoint[] }) {
184→  const max = Math.max(...data.map((d) => d.value), 1);
185→  return (
186→    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
187→      {data.map((d, i) => (
188→        <div
189→          key={i}
190→          style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center" }}
191→          title={`${d.label}: ${d.value} views`}
192→        >
193→          <div
194→            style={{
195→              width: "100%",
196→              background: "#005bd3",
197→              borderRadius: "2px 2px 0 0",
198→              height: `${(d.value / max) * 100}%`,
199→              minHeight: d.value > 0 ? "2px" : "0",
200→            }}
201→          />
202→        </div>
203→      ))}
204→    </div>
205→  );
206→}
207→
208→// ---------------------------------------------------------------------------
209→// FunnelBar sub-component (inline style — custom visualization)
210→// ---------------------------------------------------------------------------
211→
212→function FunnelBar({ rate, color }: { rate: number; color: string }) {
213→  return (
214→    <div style={{ height: "6px", background: "#e4e5e7", borderRadius: "3px", overflow: "hidden", marginTop: "4px" }}>
215→      <div
216→        style={{
217→          height: "100%",
218→          background: color,
219→          borderRadius: "3px",
220→          width: `${Math.min(100, rate)}%`,
221→          transition: "width 0.3s ease",
222→        }}
223→      />
224→    </div>
225→  );
226→}
227→
228→// ---------------------------------------------------------------------------
229→// RankBadge sub-component
230→// ---------------------------------------------------------------------------
231→
232→function RankBadge({ rank }: { rank: number }) {
233→  const colors: Record<number, string> = { 1: "#FFD700", 2: "#C0C0C0", 3: "#CD7F32" };
234→  return (
235→    <div
236→      style={{
237→        width: "28px",
238→        height: "28px",
239→        borderRadius: "50%",
240→        background: colors[rank] ?? "#e4e5e7",
241→        display: "flex",
242→        alignItems: "center",
243→        justifyContent: "center",
244→        fontSize: "12px",
245→        fontWeight: 700,
246→        flexShrink: 0,
247→        color: rank <= 3 ? "#333" : "#666",
248→      }}
249→    >
250→      {rank}
251→    </div>
252→  );
253→}
254→
255→// ---------------------------------------------------------------------------
256→// Component
257→// ---------------------------------------------------------------------------
258→
259→const PRESET_OPTIONS = [
260→  { label: "7 days", value: "7d" },
261→  { label: "30 days", value: "30d" },
262→  { label: "90 days", value: "90d" },
263→];
264→
265→export default function Analytics() {
266→  const loaderData = useLoaderData<typeof loader>();
267→  const fetcher = useFetcher<typeof loader>();
268→  const [activePreset, setActivePreset] = useState(loaderData.preset ?? "30d");
269→
270→  // Use fetcher data when available (after date range change), else loader data
271→  const data = fetcher.data ?? loaderData;
272→  const isLoading = fetcher.state !== "idle";
273→
274→  function handlePreset(preset: string) {
275→    setActivePreset(preset);
276→    fetcher.load(`/app/analytics?preset=${preset}`);
277→  }
278→
279→  // Gate check — use loaderData since data might be the fetcher result
280→  if (!data.canViewAnalytics) {
281→    return (
282→      <s-page heading="Analytics">
283→        <s-section>
284→          <s-banner tone="warning" heading="Analytics is a Growth plan feature">
285→            <s-stack direction="block" gap="base">
286→              <s-text>
287→                Track how customers interact with your size charts. See chart views, click-through rates,
288→                AI recommendation usage, and conversion impact — all in one dashboard.
289→              </s-text>
290→              <s-stack direction="inline" gap="base">
291→                <s-button variant="primary" href="/app/pricing">Upgrade to Growth — $9.99/mo</s-button>
292→                <s-button href="/app/pricing">Compare all plans</s-button>
293→              </s-stack>
294→            </s-stack>
295→          </s-banner>
296→        </s-section>
297→
298→        <s-section heading="What you'll unlock">
299→          <s-stack direction="inline" gap="base">
300→            <s-box padding="base" borderWidth="base" borderRadius="base">
301→              <s-stack direction="block" gap="small-200">
302→                <s-heading>Chart Views</s-heading>
303→                <s-text color="subdued">See exactly how many customers open your size charts by product and date range.</s-text>
304→              </s-stack>
305→            </s-box>
306→            <s-box padding="base" borderWidth="base" borderRadius="base">
307→              <s-stack direction="block" gap="small-200">
308→                <s-heading>Conversion Funnel</s-heading>
309→                <s-text color="subdued">Measure the path from chart view to AI recommendation to add-to-cart.</s-text>
310→              </s-stack>
311→            </s-box>
312→            <s-box padding="base" borderWidth="base" borderRadius="base">
313→              <s-stack direction="block" gap="small-200">
314→                <s-heading>Top Charts</s-heading>
315→                <s-text color="subdued">Identify which size charts drive the most customer engagement.</s-text>
316→              </s-stack>
317→            </s-box>
318→          </s-stack>
319→        </s-section>
320→
321→      </s-page>
322→    );
323→  }
324→
325→  const { stats, topChartsWithNames, dailyTrend } = data;
326→  const hasData = stats !== null && stats.totalViews > 0;
327→  const canViewReturnAttribution = hasFeature(data.plan.id, "returnAttribution");
328→
329→  return (
330→    <s-page heading="Analytics">
331→      {/* Primary action — date range controls */}
332→      <s-button-group slot="primary-action">
333→        {PRESET_OPTIONS.map((opt) => (
334→          <s-button
335→            key={opt.value}
336→            variant={activePreset === opt.value ? "primary" : undefined}
337→            onClick={() => handlePreset(opt.value)}
338→            disabled={isLoading}
339→          >
340→            {opt.label}
341→          </s-button>
342→        ))}
343→      </s-button-group>
344→
345→      {/* ================================================================ */}
346→      {/* UPGRADE BANNER — return attribution (Pro feature)                 */}
347→      {/* ================================================================ */}
348→      {!canViewReturnAttribution && hasData && (
349→        <s-section>
350→          <s-banner tone="info" heading="Unlock Return Attribution — Pro plan">
351→            <s-stack direction="inline" gap="base">
352→              <s-text>
353→                Connect size chart interactions directly to return rates. See exactly how much revenue your size charts protect.
354→              </s-text>
355→              <s-button href="/app/pricing">Upgrade to Pro</s-button>
356→            </s-stack>
357→          </s-banner>
358→        </s-section>
359→      )}
360→
361→      {/* ================================================================ */}
362→      {/* EMPTY STATE                                                        */}
363→      {/* ================================================================ */}
364→      {!hasData && (
365→        <s-section>
366→          <s-box padding="large-200" borderWidth="base" borderRadius="base">
367→            <s-stack direction="block" gap="base">
368→              <s-heading>No data yet for this period</s-heading>
369→              <s-text color="subdued">
370→                Analytics data appears as soon as customers start viewing your size charts on your storefront.
371→                Make sure your widget is enabled and a size chart is assigned to at least one product.
372→              </s-text>
373→              <s-stack direction="inline" gap="base">
374→                <s-button variant="primary" href="/app/size-charts">Manage size charts</s-button>
375→                <s-button href="/app/widget">Check widget settings</s-button>
376→              </s-stack>
377→            </s-stack>
378→          </s-box>
379→        </s-section>
380→      )}
381→
382→      {/* ================================================================ */}
383→      {/* STATS OVERVIEW CARDS                                              */}
384→      {/* ================================================================ */}
385→      {stats !== null && (
386→        <s-section heading="Overview">
387→          <s-stack direction="inline" gap="base">
388→            <s-box padding="base" borderWidth="base" borderRadius="base">
389→              <s-stack direction="block" gap="small-200">
390→                <s-heading>{isLoading ? "—" : stats.totalViews.toLocaleString()}</s-heading>
391→                <s-text>Total Views</s-text>
392→                <s-text color="subdued">Size chart opens</s-text>
393→              </s-stack>
394→            </s-box>
395→
396→            <s-box padding="base" borderWidth="base" borderRadius="base">
397→              <s-stack direction="block" gap="small-200">
398→                <s-heading>{isLoading ? "—" : stats.totalClicks.toLocaleString()}</s-heading>
399→                <s-text>Interactions</s-text>
400→                <s-text color="subdued">Clicks within chart</s-text>
401→              </s-stack>
402→            </s-box>
403→
404→            <s-box padding="base" borderWidth="base" borderRadius="base">
405→              <s-stack direction="block" gap="small-200">
406→                <s-heading>{isLoading ? "—" : stats.totalRecommendations.toLocaleString()}</s-heading>
407→                <s-text>AI Recommendations</s-text>
408→                <s-text color="subdued">Sizes suggested by AI</s-text>
409→              </s-stack>
410→            </s-box>
411→
412→            <s-box padding="base" borderWidth="base" borderRadius="base">
413→              <s-stack direction="block" gap="small-200">
414→                <s-heading>{isLoading ? "—" : stats.totalConverts.toLocaleString()}</s-heading>
415→                <s-text>Conversions</s-text>
416→                <s-text color="subdued">Add-to-cart after chart</s-text>
417→              </s-stack>
418→            </s-box>
419→          </s-stack>
420→        </s-section>
421→      )}
422→
423→      {/* ================================================================ */}
424→      {/* DAILY TREND CHART                                                  */}
425→      {/* ================================================================ */}
426→      {hasData && dailyTrend.length > 0 && (
427→        <s-section heading="Daily Views Trend">
428→          <s-box padding="base" borderWidth="base" borderRadius="base">
429→            <s-stack direction="block" gap="small-200">
430→              <s-text color="subdued">Chart views per day across the selected period</s-text>
431→              <BarChart data={dailyTrend} />
432→              <s-stack direction="inline" gap="base">
433→                <s-text color="subdued">{dailyTrend[0]?.label ?? ""}</s-text>
434→                <s-text color="subdued">{dailyTrend[dailyTrend.length - 1]?.label ?? ""}</s-text>
435→              </s-stack>
436→            </s-stack>
437→          </s-box>
438→        </s-section>
439→      )}
440→
441→      {/* ================================================================ */}
442→      {/* CONVERSION FUNNEL                                                  */}
443→      {/* ================================================================ */}
444→      {hasData && stats !== null && (
445→        <s-section heading="Conversion Funnel">
446→          <s-stack direction="block" gap="small-200">
447→            <s-box padding="base" borderWidth="base" borderRadius="base">
448→              <s-stack direction="block" gap="small-200">
449→                <s-stack direction="inline" gap="base">
450→                  <s-text>Views → Interactions</s-text>
451→                  <s-badge tone={parseFloat(stats.clickRate) >= 20 ? "success" : "neutral"}>
452→                    {stats.clickRate}%
453→                  </s-badge>
454→                </s-stack>
455→                <s-text color="subdued">
456→                  {stats.totalClicks.toLocaleString()} of {stats.totalViews.toLocaleString()} chart viewers clicked inside
457→                </s-text>
458→                <FunnelBar rate={parseFloat(stats.clickRate)} color="#005bd3" />
459→              </s-stack>
460→            </s-box>
461→
462→            <s-box padding="base" borderWidth="base" borderRadius="base">
463→              <s-stack direction="block" gap="small-200">
464→                <s-stack direction="inline" gap="base">
465→                  <s-text>Interactions → AI Recommendations</s-text>
466→                  <s-badge tone={parseFloat(stats.recommendRate) >= 30 ? "success" : "neutral"}>
467→                    {stats.recommendRate}%
468→                  </s-badge>
469→                </s-stack>
470→                <s-text color="subdued">
471→                  {stats.totalRecommendations.toLocaleString()} customers used the AI size recommender
472→                </s-text>
473→                <FunnelBar rate={parseFloat(stats.recommendRate)} color="#2c7be5" />
474→              </s-stack>
475→            </s-box>
476→
477→            <s-box padding="base" borderWidth="base" borderRadius="base">
478→              <s-stack direction="block" gap="small-200">
479→                <s-stack direction="inline" gap="base">
480→                  <s-text>Recommendations → Conversions</s-text>
481→                  <s-badge tone={parseFloat(stats.convertRate) >= 40 ? "success" : "neutral"}>
482→                    {stats.convertRate}%
483→                  </s-badge>
484→                </s-stack>
485→                <s-text color="subdued">
486→                  {stats.totalConverts.toLocaleString()} customers added to cart after receiving a recommendation
487→                </s-text>
488→                <FunnelBar rate={parseFloat(stats.convertRate)} color="#1a73e8" />
489→              </s-stack>
490→            </s-box>
491→
492→            <s-box padding="base" borderWidth="base" borderRadius="base">
493→              <s-stack direction="block" gap="small-200">
494→                <s-stack direction="inline" gap="base">
495→                  <s-text>Overall: Views → Conversions</s-text>
496→                  <s-badge tone={parseFloat(stats.overallConvertRate) >= 5 ? "success" : "neutral"}>
497→                    {stats.overallConvertRate}%
498→                  </s-badge>
499→                </s-stack>
500→                <s-text color="subdued">
501→                  End-to-end conversion rate — customers who viewed a chart and then added to cart
502→                </s-text>
503→                <FunnelBar rate={parseFloat(stats.overallConvertRate) * 5} color="#16a34a" />
504→              </s-stack>
505→            </s-box>
506→          </s-stack>
507→        </s-section>
508→      )}
509→
510→      {/* ================================================================ */}
511→      {/* TOP CHARTS BY VIEWS                                               */}
512→      {/* ================================================================ */}
513→      <s-section heading="Top Size Charts">
514→        {topChartsWithNames.length === 0 ? (
515→          <s-text color="subdued">
516→            No chart views in this period. Data appears once customers start viewing your size charts.
517→          </s-text>
518→        ) : (
519→          <s-stack direction="block" gap="small-200">
520→            {topChartsWithNames.map((chart) => (
521→              <s-box key={chart.chartId ?? chart.rank} padding="base" borderWidth="base" borderRadius="base">
522→                <s-stack direction="inline" gap="base">
523→                  <RankBadge rank={chart.rank} />
524→                  <s-stack direction="block" gap="small-100">
525→                    <s-link href={chart.chartId ? `/app/size-charts/${chart.chartId}` : "/app/size-charts"}>
526→                      {chart.chartName}
527→                    </s-link>
528→                    <s-text color="subdued">{chart.views.toLocaleString()} view{chart.views !== 1 ? "s" : ""}</s-text>
529→                  </s-stack>
530→                </s-stack>
531→              </s-box>
532→            ))}
533→          </s-stack>
534→        )}
535→      </s-section>
536→
537→      {/* ================================================================ */}
538→      {/* INSIGHTS + UPSELL (inline)                                         */}
539→      {/* ================================================================ */}
540→      {hasData && stats !== null && (parseFloat(stats.clickRate) < 10 || parseFloat(stats.recommendRate) < 20) && (
541→        <s-section heading="Insights">
542→          <s-stack direction="inline" gap="base">
543→            {parseFloat(stats.clickRate) < 10 && (
544→              <s-box padding="base" borderWidth="base" borderRadius="base">
545→                <s-stack direction="block" gap="small-200">
546→                  <s-badge tone="warning">Low click rate</s-badge>
547→                  <s-text color="subdued">
548→                    Below 10% — try moving your widget higher on the product page.
549→                  </s-text>
550→                </s-stack>
551→              </s-box>
552→            )}
553→            {parseFloat(stats.recommendRate) < 20 && (
554→              <s-box padding="base" borderWidth="base" borderRadius="base">
555→                <s-stack direction="block" gap="small-200">
556→                  <s-badge tone="warning">AI underused</s-badge>
557→                  <s-text color="subdued">
558→                    Fewer than 20% of interactions use the AI recommender.
559→                  </s-text>
560→                </s-stack>
561→              </s-box>
562→            )}
563→          </s-stack>
564→        </s-section>
565→      )}
566→
567→      {!canViewReturnAttribution && (
568→        <s-section>
