458→export default function WidgetCustomizer() {
459→  const { config: serverConfig } = useLoaderData<typeof loader>();
460→  const fetcher = useFetcher<typeof action>();
461→  const shopify = useAppBridge();
462→
463→  const [config, setConfig] = useState<LocalConfig>({
464→    displayMode: serverConfig.displayMode,
465→    position: serverConfig.position,
466→    triggerType: serverConfig.triggerType,
467→    primaryColor: serverConfig.primaryColor,
468→    successColor: serverConfig.successColor,
469→    errorColor: serverConfig.errorColor,
470→    backgroundColor: serverConfig.backgroundColor,
471→    textColor: serverConfig.textColor,
472→    borderRadius: serverConfig.borderRadius,
473→    heading: serverConfig.heading,
474→    placeholder: serverConfig.placeholder,
475→    buttonText: serverConfig.buttonText,
476→    successMessage: serverConfig.successMessage,
477→    errorMessage: serverConfig.errorMessage,
478→    showRecommender: serverConfig.showRecommender,
479→    customCss: serverConfig.customCss,
480→  });
481→
482→  const isLoading = fetcher.state !== "idle";
483→
484→  useEffect(() => {
485→    if (fetcher.data && "ok" in fetcher.data) {
486→      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
487→    } else if (fetcher.data && "error" in fetcher.data) {
488→      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
489→    }
