import { useEffect, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  TextField,
  Checkbox,
  Box,
  Divider,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface LocalConfig {
  displayMode: string;
  position: string;
  triggerType: string;
  primaryColor: string;
  successColor: string;
  errorColor: string;
  backgroundColor: string;
  textColor: string;
  borderRadius: string;
  heading: string;
  placeholder: string;
  buttonText: string;
  successMessage: string;
  errorMessage: string;
  showRecommender: boolean;
  customCss: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });

  return {
    config: config ?? {
      displayMode: "popup",
      position: "bottom-right",
      triggerType: "button",
      primaryColor: "#000000",
      successColor: "#16a34a",
      errorColor: "#dc2626",
      backgroundColor: "#ffffff",
      textColor: "#111111",
      borderRadius: "8",
      heading: "Size Guide",
      placeholder: "Select your size",
      buttonText: "Find My Size",
      successMessage: "This size should fit you well!",
      errorMessage: "We couldn't determine your size. Please refer to the chart.",
      showRecommender: true,
      customCss: "",
    },
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  try {
    const data = {
      displayMode: (formData.get("displayMode") as string) || "popup",
      position: (formData.get("position") as string) || "bottom-right",
      triggerType: (formData.get("triggerType") as string) || "button",
      primaryColor: (formData.get("primaryColor") as string) || "#000000",
      successColor: (formData.get("successColor") as string) || "#16a34a",
      errorColor: (formData.get("errorColor") as string) || "#dc2626",
      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
      textColor: (formData.get("textColor") as string) || "#111111",
      borderRadius: (formData.get("borderRadius") as string) || "8",
      heading: (formData.get("heading") as string) || "Size Guide",
      placeholder: (formData.get("placeholder") as string) || "Select your size",
      buttonText: (formData.get("buttonText") as string) || "Find My Size",
      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
      showRecommender: formData.get("showRecommender") === "true",
      customCss: (formData.get("customCss") as string) || "",
    };

    await db.widgetConfig.upsert({
      where: { shop: session.shop },
      update: data,
      create: { shop: session.shop, ...data },
    });
    return { ok: true, message: "Widget settings saved" };
  } catch (error) {
    return {
      error: error instanceof Error ? error.message : "An unexpected error occurred",
    };
  }
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function ColorPickerField({
  label,
  value,
  onChange,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
}) {
  return (
    <Card>
      <BlockStack gap="200">
        <Text as="p" variant="bodyMd">{label}</Text>
        <InlineStack gap="200" blockAlign="center">
          <div
            style={{
              width: "32px",
              height: "32px",
              borderRadius: "6px",
              border: "1px solid #c9cccf",
              overflow: "hidden",
              flexShrink: 0,
              position: "relative",
              cursor: "pointer",
            }}
          >
            <input
              type="color"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              style={{
                position: "absolute",
                inset: 0,
                opacity: 0,
                width: "100%",
                height: "100%",
                cursor: "pointer",
                padding: 0,
                border: "none",
              }}
            />
            <div style={{ width: "100%", height: "100%", backgroundColor: value }} />
          </div>
          <TextField
            label=""
            labelHidden
            value={value}
            onChange={(val) => onChange(val)}
            maxLength={7}
            autoComplete="off"
          />
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

function DisplayModeCard({
  value,
  label,
  description,
  benefit,
  selected,
  onSelect,
}: {
  value: string;
  label: string;
  description: string;
  benefit: string;
  selected: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div style={{ flex: "1 1 0", minWidth: "140px" }}>
      <div onClick={() => onSelect(value)} style={{ cursor: "pointer" }}>
        <Box
          padding="400"
          borderWidth={selected ? "050" : "025"}
          borderColor={selected ? "border-focus" : "border"}
          borderRadius="200"
          background={selected ? "bg-surface-selected" : "bg-surface"}
        >
          <BlockStack gap="200">
            <InlineStack gap="200" blockAlign="center">
              <Text as="p" variant="bodyMd" fontWeight="semibold">{label}</Text>
              {selected && <Badge tone="info">Active</Badge>}
            </InlineStack>
            <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
            <Text as="p" variant="bodyMd" tone="subdued">Best for: {benefit}</Text>
          </BlockStack>
        </Box>
      </div>
    </div>
  );
}

function PositionGrid({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) {
  const positions = [
    { id: "top-left", label: "Top Left" },
    { id: "top-right", label: "Top Right" },
    { id: "bottom-left", label: "Bottom Left" },
    { id: "bottom-right", label: "Bottom Right" },
  ];

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "1fr 1fr",
        gap: "8px",
        maxWidth: "320px",
      }}
    >
      {positions.map((pos) => {
        const isSelected = value === pos.id;
        return (
          <div key={pos.id} onClick={() => onChange(pos.id)} style={{ cursor: "pointer" }}>
            <Box
              padding="400"
              borderWidth={isSelected ? "050" : "025"}
              borderColor={isSelected ? "border-focus" : "border"}
              borderRadius="200"
              background={isSelected ? "bg-surface-selected" : "bg-surface"}
            >
              <Text as="p" variant="bodyMd" tone={isSelected ? undefined : "subdued"}>{pos.label}</Text>
            </Box>
          </div>
        );
      })}
    </div>
  );
}

function TriggerTypeSelector({
  value,
  onChange,
}: {
  value: string;
  onChange: (v: string) => void;
}) {
  const types = [
    { id: "button", label: "Button", desc: "Prominent CTA button" },
    { id: "link", label: "Link", desc: "Subtle text link" },
    { id: "tab", label: "Tab", desc: "Sticky tab on the edge" },
  ];

  return (
    <InlineStack gap="400">
      {types.map((t) => {
        const isSelected = value === t.id;
        return (
          <div key={t.id} onClick={() => onChange(t.id)} style={{ cursor: "pointer" }}>
            <Box
              padding="400"
              borderWidth={isSelected ? "050" : "025"}
              borderColor={isSelected ? "border-focus" : "border"}
              borderRadius="200"
              background={isSelected ? "bg-surface-selected" : "bg-surface"}
            >
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd" fontWeight="semibold">{t.label}</Text>
                <Text as="p" variant="bodyMd" tone="subdued">{t.desc}</Text>
              </BlockStack>
            </Box>
          </div>
        );
      })}
    </InlineStack>
  );
}

// ---------------------------------------------------------------------------
// Live Preview — intentional custom styling kept as-is
// ---------------------------------------------------------------------------

function WidgetPreview({ config }: { config: LocalConfig }) {
  const radius = `${config.borderRadius}px`;

  return (
    <div
      style={{
        backgroundColor: config.backgroundColor,
        borderRadius: radius,
        border: `1px solid ${config.primaryColor}33`,
        padding: "20px",
        fontFamily: "system-ui, sans-serif",
        boxShadow: "0 4px 16px rgba(0,0,0,0.08)",
        maxWidth: "320px",
        width: "100%",
      }}
    >
      {/* Header */}
      <div
        style={{
          borderBottom: `1px solid ${config.primaryColor}22`,
          paddingBottom: "12px",
          marginBottom: "16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span
          style={{
            fontSize: "16px",
            fontWeight: 700,
            color: config.textColor,
          }}
        >
          {config.heading || "Size Guide"}
        </span>
        <span
          style={{
            fontSize: "18px",
            color: "#8c9196",
            cursor: "pointer",
            lineHeight: 1,
          }}
        >
          ×
        </span>
      </div>

      {/* Size Chart Table */}
      <div
        style={{
          borderRadius: "6px",
          overflow: "hidden",
          border: "1px solid #e3e5e7",
          marginBottom: "16px",
        }}
      >
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: "12px" }}>
          <thead>
            <tr style={{ backgroundColor: `${config.primaryColor}15` }}>
              {["Size", "S", "M", "L", "XL"].map((h) => (
                <th
                  key={h}
                  style={{
                    padding: "8px 10px",
                    textAlign: "center",
                    fontWeight: 600,
                    color: config.textColor,
                    borderRight: "1px solid #e3e5e7",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {[
              { label: "Bust", values: ["32", "34", "36", "38"] },
              { label: "Waist", values: ["26", "28", "30", "32"] },
              { label: "Hips", values: ["34", "36", "38", "40"] },
            ].map((row, ri) => (
              <tr
                key={row.label}
                style={{ backgroundColor: ri % 2 === 0 ? "#fff" : "#f9fafb" }}
              >
                <td
                  style={{
                    padding: "7px 10px",
                    fontWeight: 600,
                    color: config.textColor,
                    borderRight: "1px solid #e3e5e7",
                    borderTop: "1px solid #e3e5e7",
                    fontSize: "11px",
                  }}
                >
                  {row.label}
                </td>
                {row.values.map((v, vi) => (
                  <td
                    key={vi}
                    style={{
                      padding: "7px 10px",
                      textAlign: "center",
                      color: config.textColor,
                      borderRight: "1px solid #e3e5e7",
                      borderTop: "1px solid #e3e5e7",
                      fontSize: "11px",
                    }}
                  >
                    {v}"
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* CTA Button */}
      {config.showRecommender && (
        <button
          style={{
            width: "100%",
            padding: "10px 16px",
            backgroundColor: config.primaryColor,
            color: "#fff",
            border: "none",
            borderRadius: radius,
            fontSize: "14px",
            fontWeight: 600,
            cursor: "pointer",
            marginBottom: "12px",
          }}
        >
          {config.buttonText || "Find My Size"}
        </button>
      )}

      {/* Success Message */}
      <div
        style={{
          backgroundColor: `${config.successColor}15`,
          border: `1px solid ${config.successColor}40`,
          borderRadius: "6px",
          padding: "10px 12px",
          display: "flex",
          alignItems: "flex-start",
          gap: "8px",
        }}
      >
        <span style={{ color: config.successColor, fontSize: "14px", flexShrink: 0 }}>✓</span>
        <span style={{ fontSize: "12px", color: config.textColor, lineHeight: 1.4 }}>
          {config.successMessage || "This size should fit you well!"}
        </span>
      </div>

      {/* Footer badge */}
      <div
        style={{
          marginTop: "12px",
          textAlign: "center",
          fontSize: "10px",
          color: "#8c9196",
        }}
      >
        Powered by Size Chart &amp; Recommender
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

export default function WidgetCustomizer() {
  const { config: serverConfig } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const [config, setConfig] = useState<LocalConfig>({
    displayMode: serverConfig.displayMode,
    position: serverConfig.position,
    triggerType: serverConfig.triggerType,
    primaryColor: serverConfig.primaryColor,
    successColor: serverConfig.successColor,
    errorColor: serverConfig.errorColor,
    backgroundColor: serverConfig.backgroundColor,
    textColor: serverConfig.textColor,
    borderRadius: serverConfig.borderRadius,
    heading: serverConfig.heading,
    placeholder: serverConfig.placeholder,
    buttonText: serverConfig.buttonText,
    successMessage: serverConfig.successMessage,
    errorMessage: serverConfig.errorMessage,
    showRecommender: serverConfig.showRecommender,
    customCss: serverConfig.customCss,
  });

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
    setConfig((prev) => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    const formData = new FormData();
    formData.set("displayMode", config.displayMode);
    formData.set("position", config.position);
    formData.set("triggerType", config.triggerType);
    formData.set("primaryColor", config.primaryColor);
    formData.set("successColor", config.successColor);
    formData.set("errorColor", config.errorColor);
    formData.set("backgroundColor", config.backgroundColor);
    formData.set("textColor", config.textColor);
    formData.set("borderRadius", config.borderRadius);
    formData.set("heading", config.heading);
    formData.set("placeholder", config.placeholder);
    formData.set("buttonText", config.buttonText);
