                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">What you&apos;ll unlock</Text>
                  <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Chart Views</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">See exactly how many customers open your size charts by product and date range.</Text>
                      </BlockStack>
                    </Card>
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Conversion Funnel</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Measure the path from chart view to AI recommendation to add-to-cart.</Text>
                      </BlockStack>
                    </Card>
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Top Charts</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Identify which size charts drive the most customer engagement.</Text>
                      </BlockStack>
                    </Card>
                  </InlineGrid>
                </BlockStack>
              </Card>
            </BlockStack>
          </Layout.Section>
