                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalClicks.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">Interactions</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Clicks within chart</Text>
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalRecommendations.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">AI Recommendations</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Sizes suggested by AI</Text>
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalConverts.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">Conversions</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Add-to-cart after chart</Text>
                      </BlockStack>
                    </Card>
                  </InlineGrid>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* DAILY TREND CHART                                                */}
            {/* ================================================================ */}
            {hasData && dailyTrend.length > 0 && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Daily Views Trend</Text>
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd" tone="subdued">Chart views per day across the selected period</Text>
                    <BarChart data={dailyTrend} />
                    <InlineStack align="space-between">
                      <Text as="p" variant="bodyMd" tone="subdued">{dailyTrend[0]?.label ?? ""}</Text>
                      <Text as="p" variant="bodyMd" tone="subdued">{dailyTrend[dailyTrend.length - 1]?.label ?? ""}</Text>
                    </InlineStack>
                  </BlockStack>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* CONVERSION FUNNEL                                                */}
            {/* ================================================================ */}
            {hasData && stats !== null && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Conversion Funnel</Text>
                  <BlockStack gap="200">
                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Views → Interactions</Text>
                          <Badge tone={parseFloat(stats.clickRate) >= 20 ? "success" : "info"}>
                            {stats.clickRate}%
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalClicks.toLocaleString()} of {stats.totalViews.toLocaleString()} chart viewers clicked inside
                        </Text>
                        <FunnelBar rate={parseFloat(stats.clickRate)} color="#005bd3" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Interactions → AI Recommendations</Text>
                          <Badge tone={parseFloat(stats.recommendRate) >= 30 ? "success" : "info"}>
                            {stats.recommendRate}%
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalRecommendations.toLocaleString()} customers used the AI size recommender
                        </Text>
                        <FunnelBar rate={parseFloat(stats.recommendRate)} color="#2c7be5" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Recommendations → Conversions</Text>
                          <Badge tone={parseFloat(stats.convertRate) >= 40 ? "success" : "info"}>
                            {stats.convertRate}%
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalConverts.toLocaleString()} customers added to cart after receiving a recommendation
                        </Text>
                        <FunnelBar rate={parseFloat(stats.convertRate)} color="#1a73e8" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Overall: Views → Conversions</Text>
                          <Badge tone={parseFloat(stats.overallConvertRate) >= 5 ? "success" : "info"}>
                            {stats.overallConvertRate}%
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          End-to-end conversion rate — customers who viewed a chart and then added to cart
                        </Text>
                        <FunnelBar rate={parseFloat(stats.overallConvertRate) * 5} color="#16a34a" />
                      </BlockStack>
                    </Card>
                  </BlockStack>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* TOP CHARTS BY VIEWS                                              */}
            {/* ================================================================ */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Top Size Charts</Text>
                {topChartsWithNames.length === 0 ? (
                  <Text as="p" variant="bodyMd" tone="subdued">
                    No chart views in this period. Data appears once customers start viewing your size charts.
                  </Text>
                ) : (
                  <BlockStack gap="200">
                    {topChartsWithNames.map((chart) => (
                      <Card key={chart.chartId ?? chart.rank}>
                        <InlineStack gap="400" blockAlign="center">
                          <RankBadge rank={chart.rank} />
                          <BlockStack gap="100">
                            <Button
                              variant="plain"
                              url={chart.chartId ? `/app/size-charts/${chart.chartId}` : "/app/size-charts"}
                            >
                              {chart.chartName}
                            </Button>
                            <Text as="p" variant="bodyMd" tone="subdued">{chart.views.toLocaleString()} view{chart.views !== 1 ? "s" : ""}</Text>
                          </BlockStack>
                        </InlineStack>
                      </Card>
                    ))}
                  </BlockStack>
                )}
              </BlockStack>
            </Card>

            {/* ================================================================ */}
            {/* INSIGHTS + UPSELL (inline)                                       */}
            {/* ================================================================ */}
            {hasData && stats !== null && (parseFloat(stats.clickRate) < 10 || parseFloat(stats.recommendRate) < 20) && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Insights</Text>
                  <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                    {parseFloat(stats.clickRate) < 10 && (
                      <Card>
                        <BlockStack gap="200">
                          <Badge tone="warning">Low click rate</Badge>
                          <Text as="p" variant="bodyMd" tone="subdued">
                            Below 10% — try moving your widget higher on the product page.
                          </Text>
                        </BlockStack>
                      </Card>
                    )}
                    {parseFloat(stats.recommendRate) < 20 && (
                      <Card>
                        <BlockStack gap="200">
                          <Badge tone="warning">AI underused</Badge>
                          <Text as="p" variant="bodyMd" tone="subdued">
                            Fewer than 20% of interactions use the AI recommender.
                          </Text>
                        </BlockStack>
                      </Card>
                    )}
                  </InlineGrid>
                </BlockStack>
              </Card>
            )}

            {!canViewReturnAttribution && (
              <Banner tone="info" title="Unlock Return Attribution">
                <InlineStack gap="400" blockAlign="center">
                  <Text as="p" variant="bodyMd">
                    See which charts reduce returns and calculate revenue saved. Available on Pro plan.
                  </Text>
                  <Button url="/app/pricing">Upgrade to Pro</Button>
                </InlineStack>
              </Banner>
            )}

          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}
